import{_ as a,c as i,o as e,b0 as n}from"./chunks/framework.Becqh7-x.js";const l="/linux-dev-docs/assets/image-20260106100723353.BPaQfN5L.png",t="/linux-dev-docs/assets/image-20220512191620321.BXV1J3hP.png",p="/linux-dev-docs/assets/image-20241015072020385.BJRBjAuQ.png",r="/linux-dev-docs/assets/image-20241015001933698.pGZ3-1te.png",h="/linux-dev-docs/assets/image-20241015002104266.CDOjxWwV.png",d="/linux-dev-docs/assets/image-20241015002237204.CUDHDa8N.png",o="/linux-dev-docs/assets/image-20241015072900530.D8j34enR.png",y=JSON.parse('{"title":"LV010-工具链安装","description":null,"frontmatter":{"title":"LV010-工具链安装","date":"2026-01-06T09:18:55.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/dev-env/cros-compiling/126d2c6d3d4f0ea3c2540dc9","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-06T09:18:55.234Z","fulluuid":"3c2540dc9a9c489eb2ee457f27af1704","useduuid":"3c2540dc9"}},"headers":[],"relativePath":"sdoc/dev-env/cros-compiling/126d2c6d3d4f0ea3c2540dc9.md","filePath":"sdoc/05-开发环境/20-交叉编译/LV010-工具链安装.md","lastUpdated":1768604092000}'),c={name:"sdoc/dev-env/cros-compiling/126d2c6d3d4f0ea3c2540dc9.md"};function k(u,s,g,m,b,v){return e(),i("div",null,[...s[0]||(s[0]=[n('<h1 id="lv010-工具链安装" tabindex="-1">LV010-工具链安装 <a class="header-anchor" href="#lv010-工具链安装" aria-label="Permalink to &quot;LV010-工具链安装&quot;">​</a></h1><h2 id="一、arm-交叉编译工具链" tabindex="-1">一、ARM 交叉编译工具链 <a class="header-anchor" href="#一、arm-交叉编译工具链" aria-label="Permalink to &quot;一、ARM 交叉编译工具链&quot;">​</a></h2><h3 id="_1-下载软件包" tabindex="-1">1. 下载软件包 <a class="header-anchor" href="#_1-下载软件包" aria-label="Permalink to &quot;1. 下载软件包&quot;">​</a></h3><p>可以在下边的地址中下载 <code>4.9.4</code> 版本的交叉编译工具软件包，当然自己也可以使用更高版本啦，我是为了跟教程一致，才用的老版本，以后会玩了，可能就换新了：<a href="https://releases.linaro.org/components/toolchain/binaries/4.9-2017.01/arm-linux-gnueabihf/" target="_blank" rel="noreferrer">Linaro Releases</a></p><p><img src="'+l+`" alt="image-20260106100723353"></p><p>具体选择哪一个？我们主要是看自己开发环境，我们可以在主机中执行 <code>uname -m</code>命令来查看系统架构，要是输出x86_64，则是64位，输出是i686/i386就是32位的。这里我的ubuntu系统是64位，这里就选择下面x86_64版本的。下载完毕后，拷贝到自己 <code>Ubuntu</code> 的一个目录中：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2Sharedfiles/3Software/gcc-linaro-4.9.4-2017.01-x86_64_arm-linux-gnueabihf.tar.xz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/1Software/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后进入目录，并解压：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/1Software/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xvf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gcc-linaro-4.9.4-2017.01-x86_64_arm-linux-gnueabihf.tar.xz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_2-安装交叉编译器" tabindex="-1">2. 安装交叉编译器 <a class="header-anchor" href="#_2-安装交叉编译器" aria-label="Permalink to &quot;2. 安装交叉编译器&quot;">​</a></h3><ul><li>（1）新建存放交叉编译工具的文件夹</li></ul><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/arm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/1Software/gcc-linaro-4.9.4-2017.01-x86_64_arm-linux-gnueabihf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/arm</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>（2）添加环境变量</li></ul><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1.打开相应文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/profile</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2.文件结尾添加以下内容</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH:/usr/local/arm/gcc-linaro-4.9.4-2017.01-x86_64_arm-linux-gnueabihf/bin</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3.重启设备，使环境变量生效(最好重启下吧)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reboot</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ul><li>（3）安装相关的库（虽然写笔记的时候还不知道有啥用）</li></ul><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lsb-core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lib32stdc++6</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个库安装的时间还是有点久的。</p><ul><li>（4）验证是否成功安装交叉编译工具</li></ul><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-linux-gnueabihf-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>若成功，则会显示交叉编译工具的版本，如下图所示：</p><img src="`+t+'" alt="image-20220512191620321" style="zoom:50%;"><h2 id="二、poky-交叉编译工具链" tabindex="-1">二、Poky 交叉编译工具链 <a class="header-anchor" href="#二、poky-交叉编译工具链" aria-label="Permalink to &quot;二、Poky 交叉编译工具链&quot;">​</a></h2><p>这里要再安装一个 Poky 交叉编译工具链。这个主要是在后面编译 freetype 的时候出现报错了，发现用这个编译倒是没有问题。在这里补充一下安装方式吧。</p><blockquote><p>[4.2 安装Poky交叉编译工具链 | 正点原子在线文档](<a href="https://wiki.alientek.com/docs/Boards/Linux/IMX6U/I.MX6U" target="_blank" rel="noreferrer">https://wiki.alientek.com/docs/Boards/Linux/IMX6U/I.MX6U</a> 快速体验手册/cross compiling/install_poky/)</p></blockquote><h3 id="_1-下载安装脚本" tabindex="-1">1. 下载安装脚本 <a class="header-anchor" href="#_1-下载安装脚本" aria-label="Permalink to &quot;1. 下载安装脚本&quot;">​</a></h3><p>目前还没找到这个安装脚本应该从哪里下载，就先用正点原子官方的提供的资料里面的吧，路径是【正点原子】阿尔法 Linux 开发板（A 盘）-基础资料\\05、开发工具\\01、交叉编译器：</p><img src="'+p+'" alt="image-20241015072020385" style="zoom:50%;"><h3 id="_2-安装交叉编译器-1" tabindex="-1">2. 安装交叉编译器 <a class="header-anchor" href="#_2-安装交叉编译器-1" aria-label="Permalink to &quot;2. 安装交叉编译器&quot;">​</a></h3><p>执行下面的指令修改脚本的权限， 修改权限后可以看到此脚本颜色显示改变，说明修改成功。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fsl-imx-x11-glibc-x86_64-meta-toolchain-qt5-cortexa7hf-neon-toolchain-4.1.15-2.1.0.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>直接执行脚本安装交叉编译工具，连续敲下两次回车键确认，再输入用户密码即可。本次安装的目录为脚本所指定的默认安装的目录，后面的内核编译环境的交叉编译都是按这个安装目录去操作，所以建议用户也是默认安装到/opt/fsl-imx-x11/4.1.15-2.1.0 这个默认目录。</p><img src="'+r+'" alt="image-20241015001933698" style="zoom:48%;"><p>使用方法也十分简单，根据上面打印出来的提示，直接使能环境变量就可以了。但是在不同终端或者切换用户时需要重新使能环境变量方可使用。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/fsl-imx-x11/4.1.15-2.1.0/environment-setup-cortexa7hf-neon-poky-linux-gnueabi</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>使能环境变量后可以使用 env 指令查看生效的环境变量，下图为部分截图，可以看出使能了这个环境变量后 gcc 已经配置好编译时所用的参数，如硬浮点参数-mfpu = neon -mfloat-abi = hard。使用硬浮点交叉编译，可以使用 CPU 自带 FPU。 下图为环境变量部分截图。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><img src="'+h+`" alt="image-20241015002104266" style="zoom:75%;"><p>使用 arm-poky-linux-gnueabi-gcc -v 指令可以查看 gcc 版本，表明环境变量已经生效。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-poky-linux-gnueabi-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-poky-linux-gnueabi-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 这个更简洁一些</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><img src="`+d+'" alt="image-20241015002237204" style="zoom:77%;"><h3 id="_3-增加了哪些环境变量" tabindex="-1">3. 增加了哪些环境变量？ <a class="header-anchor" href="#_3-增加了哪些环境变量" aria-label="Permalink to &quot;3. 增加了哪些环境变量？&quot;">​</a></h3><p>我们可以 source 前后打印一下 env 看一下，大概就是这一些差异：</p><img src="'+o+'" alt="image-20241015072900530">',43)])])}const C=a(c,[["render",k]]);export{y as __pageData,C as default};
